SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.ReleaseProjects','U') IS NULL CREATE TABLE dbo.ReleaseProjects(
 ReleaseProjectId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,
 WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,PackagingVersionId UNIQUEIDENTIFIER NOT NULL,
 Status NVARCHAR(30) NOT NULL DEFAULT 'AWAITING_APPROVAL',ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,
 CurrentApprovalStep INT NOT NULL DEFAULT 1,RequiredApprovalSteps INT NOT NULL DEFAULT 2,
 ApprovedAt DATETIME2 NULL,ReleasedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
 CONSTRAINT UQ_ReleaseProjects_Project UNIQUE(ContentProjectId),CONSTRAINT FK_ReleaseProjects_Workspace FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId),CONSTRAINT FK_ReleaseProjects_Project FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId),CONSTRAINT FK_ReleaseProjects_Packaging FOREIGN KEY(PackagingVersionId) REFERENCES dbo.PackagingVersions(PackagingVersionId));
IF OBJECT_ID('dbo.ReleaseApprovalSteps','U') IS NULL CREATE TABLE dbo.ReleaseApprovalSteps(
 ReleaseApprovalStepId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ReleaseProjectId UNIQUEIDENTIFIER NOT NULL,StepNumber INT NOT NULL,StepKey NVARCHAR(80) NOT NULL,StepName NVARCHAR(200) NOT NULL,
 RequiredRoleKey NVARCHAR(80) NULL,AssignedUserId UNIQUEIDENTIFIER NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'PENDING',Decision NVARCHAR(30) NULL,Comment NVARCHAR(MAX) NULL,DecidedByUserId UNIQUEIDENTIFIER NULL,DecidedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
 CONSTRAINT UQ_ReleaseApprovalSteps UNIQUE(ReleaseProjectId,StepNumber),CONSTRAINT FK_ReleaseApprovalSteps_Release FOREIGN KEY(ReleaseProjectId) REFERENCES dbo.ReleaseProjects(ReleaseProjectId));
IF OBJECT_ID('dbo.ReleaseChecks','U') IS NULL CREATE TABLE dbo.ReleaseChecks(
 ReleaseCheckId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ReleaseProjectId UNIQUEIDENTIFIER NOT NULL,CheckKey NVARCHAR(80) NOT NULL,CheckName NVARCHAR(250) NOT NULL,Category NVARCHAR(80) NOT NULL,Severity NVARCHAR(30) NOT NULL,IsBlocking BIT NOT NULL DEFAULT 0,Status NVARCHAR(30) NOT NULL DEFAULT 'NEEDS_REVIEW',Evidence NVARCHAR(MAX) NULL,ResolvedByUserId UNIQUEIDENTIFIER NULL,ResolvedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_ReleaseChecks UNIQUE(ReleaseProjectId,CheckKey),CONSTRAINT FK_ReleaseChecks_Release FOREIGN KEY(ReleaseProjectId) REFERENCES dbo.ReleaseProjects(ReleaseProjectId));
IF OBJECT_ID('dbo.PublishingConnections','U') IS NULL CREATE TABLE dbo.PublishingConnections(
 PublishingConnectionId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,Platform NVARCHAR(60) NOT NULL,ConnectionName NVARCHAR(200) NOT NULL,AccountLabel NVARCHAR(250) NULL,ExternalAccountId NVARCHAR(250) NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'NOT_CONNECTED',ScopesJson NVARCHAR(MAX) NULL,CredentialReference NVARCHAR(500) NULL,LastHealthCheckAt DATETIME2 NULL,LastHealthStatus NVARCHAR(30) NULL,TokenExpiresAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_PublishingConnections UNIQUE(WorkspaceId,Platform,ConnectionName),CONSTRAINT FK_PublishingConnections_Workspace FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId));
IF OBJECT_ID('dbo.PublishJobs','U') IS NULL CREATE TABLE dbo.PublishJobs(
 PublishJobId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ReleaseProjectId UNIQUEIDENTIFIER NOT NULL,PlatformPackageId UNIQUEIDENTIFIER NOT NULL,PublishingConnectionId UNIQUEIDENTIFIER NULL,
 Platform NVARCHAR(60) NOT NULL,Operation NVARCHAR(30) NOT NULL DEFAULT 'PUBLISH',Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',Priority INT NOT NULL DEFAULT 50,ScheduledFor DATETIME2 NULL,StartedAt DATETIME2 NULL,CompletedAt DATETIME2 NULL,AttemptNumber INT NOT NULL DEFAULT 0,MaxAttempts INT NOT NULL DEFAULT 3,ExternalJobId NVARCHAR(500) NULL,ExternalPublicationId NVARCHAR(500) NULL,PublicationUrl NVARCHAR(1500) NULL,RequestManifestJson NVARCHAR(MAX) NULL,ResponseJson NVARCHAR(MAX) NULL,ErrorCode NVARCHAR(120) NULL,ErrorMessage NVARCHAR(MAX) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_PublishJobs_Release FOREIGN KEY(ReleaseProjectId) REFERENCES dbo.ReleaseProjects(ReleaseProjectId),CONSTRAINT FK_PublishJobs_PlatformPackage FOREIGN KEY(PlatformPackageId) REFERENCES dbo.PlatformPackages(PlatformPackageId),CONSTRAINT FK_PublishJobs_Connection FOREIGN KEY(PublishingConnectionId) REFERENCES dbo.PublishingConnections(PublishingConnectionId));
IF OBJECT_ID('dbo.PublishJobAttempts','U') IS NULL CREATE TABLE dbo.PublishJobAttempts(
 PublishJobAttemptId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PublishJobId UNIQUEIDENTIFIER NOT NULL,AttemptNumber INT NOT NULL,Status NVARCHAR(30) NOT NULL,ExternalJobId NVARCHAR(500) NULL,RequestJson NVARCHAR(MAX) NULL,ResponseJson NVARCHAR(MAX) NULL,ErrorMessage NVARCHAR(MAX) NULL,StartedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2 NULL,CONSTRAINT UQ_PublishJobAttempts UNIQUE(PublishJobId,AttemptNumber),CONSTRAINT FK_PublishJobAttempts_Job FOREIGN KEY(PublishJobId) REFERENCES dbo.PublishJobs(PublishJobId));
IF OBJECT_ID('dbo.Publications','U') IS NULL CREATE TABLE dbo.Publications(
 PublicationId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,ReleaseProjectId UNIQUEIDENTIFIER NOT NULL,PublishJobId UNIQUEIDENTIFIER NOT NULL,Platform NVARCHAR(60) NOT NULL,ExternalPublicationId NVARCHAR(500) NOT NULL,PublicationUrl NVARCHAR(1500) NULL,PublishedTitle NVARCHAR(500) NULL,PublishedAt DATETIME2 NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'PUBLISHED',Visibility NVARCHAR(40) NULL,MetadataSnapshotJson NVARCHAR(MAX) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_Publications_External UNIQUE(Platform,ExternalPublicationId),CONSTRAINT FK_Publications_Project FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId),CONSTRAINT FK_Publications_Release FOREIGN KEY(ReleaseProjectId) REFERENCES dbo.ReleaseProjects(ReleaseProjectId),CONSTRAINT FK_Publications_Job FOREIGN KEY(PublishJobId) REFERENCES dbo.PublishJobs(PublishJobId));
IF OBJECT_ID('dbo.ReleaseActivities','U') IS NULL CREATE TABLE dbo.ReleaseActivities(
 ReleaseActivityId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,ReleaseProjectId UNIQUEIDENTIFIER NOT NULL,ActivityType NVARCHAR(80) NOT NULL,Title NVARCHAR(250) NOT NULL,Details NVARCHAR(MAX) NULL,ActorType NVARCHAR(30) NOT NULL DEFAULT 'SYSTEM',ActorUserId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_ReleaseActivities_Release FOREIGN KEY(ReleaseProjectId) REFERENCES dbo.ReleaseProjects(ReleaseProjectId));
CREATE INDEX IX_PublishJobs_StatusSchedule ON dbo.PublishJobs(Status,ScheduledFor);
CREATE INDEX IX_Publications_ProjectPlatform ON dbo.Publications(ContentProjectId,Platform,PublishedAt DESC);
COMMIT TRANSACTION;
